 const tooltip=$('.scatter-tooltip'),stage=$('.scatter-stage');document.querySelectorAll('.scatter circle').forEach(point=>{const show=event=>{const stock=rows.find(s=>s.rank===+point.dataset.company);if(!stock)return;tooltip.innerHTML=`<strong>${escapeHtml(stock.name)}</strong><span>${scatterLabel} <b>${amount(stock[scatterMetric],scatterMetric)}</b></span><span>Market cap <b>${amount(stock.cap)}</b></span>`;tooltip.hidden=false;const r=point.getBoundingClientRect();positionChartTooltip(tooltip,event?.clientX??r.right,event?.clientY??r.top)};point.onpointerenter=point.onpointermove=point.onfocus=show;point.onpointerleave=point.onblur=()=>tooltip.hidden=true;point.onkeydown=e=>{if(e.key===' '){e.preventDefault();openCompany(+point.dataset.company)}}});bindCompanies();
