function scatter(rows=stocks,key='revenue'){const ss=rows.filter(s=>Number.isFinite(s[key])&&Number.isFinite(s.cap)),label=key==='earnings'?'Profit (pretax)':'Revenue',axis=n=>currency==='USD'?formatUSD(n*1e9):formatINR(n*1e9*fx);if(!ss.length)return '<div class="empty">'+label+' data is unavailable for this selection.</div>';const xmin=Math.min(0,...ss.map(s=>s[key]))*1.12,xmax=Math.max(...ss.map(s=>s[key]),1)*1.12,ymax=Math.max(...ss.map(s=>s.cap),1)*1.12;return `<svg class="scatter" viewBox="0 0 1000 400" role="img" aria-label="${label} versus market capitalization. Focus individual points for values."><text x="110" y="20">Market cap (${currency})</text>${[0,1,2,3,4].map(i=>{const y=345-i/4*300,x=110+i/4*820;return `<line x1="110" x2="930" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="98" y="${y+4}" text-anchor="end">${axis(i*ymax/4)}</text><text x="${x}" y="369" text-anchor="middle">${axis(xmin+i*(xmax-xmin)/4)}</text>`}).join('')}${xmin<0?`<line x1="${110-xmin/(xmax-xmin)*820}" x2="${110-xmin/(xmax-xmin)*820}" y1="45" y2="345" stroke="var(--muted)" stroke-dasharray="3 4"/>`:''}${ss.map(s=>`<circle tabindex="0" role="button" aria-label="${escapeHtml(s.name)}: ${label} ${axis(s[key])}, market cap ${axis(s.cap)}" data-company="${s.rank}" cx="${110+(s[key]-xmin)/(xmax-xmin)*820}" cy="${345-s.cap/ymax*300}" r="${3+Math.sqrt(s.cap)*.28}" style="fill:${s[key]<0?'var(--down)':'#3d79ca'}"><title>${escapeHtml(s.name)} · ${label} ${axis(s[key])} · Market cap ${axis(s.cap)}</title></circle>`).join('')}<text x="930" y="396" text-anchor="end">${label} (${currency})</text></svg>`}
function renderSectors(){$('#content').innerHTML=`<p class="note">Explore companies by their primary business. Sector classifications are editorial and may differ from exchange classifications.</p><div class="sector-grid">${sectorTotals().map(([k,v],i)=>`<button class="sector-card" data-sector="${k}"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${k.toUpperCase()}</span><strong>${amount(v)}</strong><small>${stocks.filter(s=>s.sector===k).length} companies <span style="float:right;color:var(--green)">Explore →</span></small></button>`).join('')}</div>`;document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{sector=b.dataset.sector;query='';page=1;location.hash='rankings'})}
function renderCompare(){const selected=compare.map(t=>stocks.find(s=>s.ticker===t)).filter(Boolean);$('#content').innerHTML=`<p class="note">Choose up to four companies. Missing data stays blank; metrics have different source dates.</p><div class="compare-picks"><select id="add-company" aria-label="Add a company for comparison"><option value="">+ Add a company</option>${stocks.filter(s=>!compare.includes(s.ticker)).map(s=>option(s.ticker,s.name)).join('')}</select>${selected.map(s=>`<button data-remove="${s.ticker}">${s.name} ×</button>`).join('')}</div>${selected.length?`${compareOverlay(selected)}<div class="table-wrap compare-table-wrap"><table class="compare-table" style="--compare-count:${selected.length}"><colgroup><col class="compare-metric-col">${selected.map(()=>'<col class="compare-company-col">').join('')}</colgroup><thead><tr><th class="left">Financial metric</th>${selected.map(s=>`<th><button data-company="${s.rank}">${s.name} ↗</button><br><small>${s.ticker}</small></th>`).join('')}</tr></thead><tbody>${Object.entries(metrics).map(([k,l])=>`<tr><td>${l}</td>${selected.map(s=>`<td>${k==='price'?stockPrice(s):amount(s[k],k)}</td>`).join('')}</tr>`).join('')}<tr><td>Source price</td>${selected.map(s=>`<td>${stockPrice(s)}${feedMode==='live'?`<small class="live-time">${s.lastTrade?new Date(s.lastTrade).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Waiting for quote'}${s.lastTrade?' IST':''}</small>`:''}</td>`).join('')}</tr></tbody></table></div>`:`<div class="empty"><h3>Discover the differences.</h3><p>Select companies above or use the compare checkboxes in Rankings.</p></div>`}`;$('#add-company').onchange=e=>{if(!e.target.value)return;if(compare.length>=4){toast('Remove a company before adding another.');return}compare.push(e.target.value);save('isv-compare',compare);renderCompare()};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{compare=compare.filter(t=>t!==b.dataset.remove);save('isv-compare',compare);renderCompare()});bindRelativeOverlay(selected);document.querySelectorAll('[data-compare-range]').forEach(b=>b.onclick=()=>{compareTimeline=30;renderCompare()});document.querySelectorAll('[data-overlay-toggle]').forEach(b=>b.onclick=()=>{const visible=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',visible);document.querySelectorAll('[data-overlay]').forEach(line=>{if(line.dataset.overlay===b.dataset.overlayToggle)line.style.display=visible?'':'none'})});bindCompanies()}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function slug(s){return ({'Tata Consultancy Services':'tata-consultancy-services','Sun Pharmaceutical':'sun-pharmaceutical','HDFC Bank':'hdfc-bank','ICICI Bank':'icici-bank','State Bank of India':'state-bank-of-india','Infosys':'infosys'})[s.name]||s.name.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function sourceCompany(s,path){return s.source?s.source.replace(/marketcap\/$/,path+'/'):`https://companiesmarketcap.com/${slug(s)}/${path}/`}
const paths={cap:'marketcap',earnings:'earnings',revenue:'revenue',pe:'pe-ratio',dividend:'dividend-yield',margin:'operating-margin',employees:'number-of-employees',assets:'total-assets',liabilities:'total-liabilities',debt:'total-debt',cash:'cash-on-hand',netAssets:'net-assets',pb:'pb-ratio',ps:'ps-ratio',eps:'eps',shares:'shares-outstanding',borrow:'cost-to-borrow'};
function openCompany(rank){const s=stocks.find(x=>x.rank===rank);if(!s)return;location.hash='stock/'+encodeURIComponent(s.ticker)+'/cap'}
function showDetailMetric(s,k){$('#detail-metric').innerHTML=`<h3>${metrics[k]}</h3><div class="detail-value">${k==='price'?stockPrice(s):amount(s[k],k)}</div><p class="note">${s[k]!=null?'Reported value from the linked ranking snapshot.':'Not available in the loaded source snapshot.'}${k==='earnings'?' Earnings are the source’s pretax earnings measure, not net income.':''}</p><a class="source-link" target="_blank" rel="noopener" href="${db.sources[k]||sourceCompany(s,paths[k])}">View ${metrics[k].toLowerCase()} source ↗</a>`}
function renderAbout(){$('#content').innerHTML=`<article class="card about"><span class="eyebrow">TRANSPARENT BY DESIGN</span><h3>A snapshot, with its context.</h3><p>IndiaStockView is inspired by CompaniesMarketCap. The offline snapshot contains ${snapshotStocks.length} Indian companies from the reference’s 595-company universe. It is not yet an exhaustive database of NSE and BSE securities.</p><ul><li>Retrieved on 30 October 2026. Market-cap source crawled that day; earnings and revenue rankings expanded across all six pages on 31 October 2026, P/E two days earlier, operating margin the previous week, and dividend yield three weeks earlier. Employee reporting periods vary by company.</li><li>Prices and market caps are USD source values. HDB, IBN, INFY, WIT and RDY may be overseas depositary-receipt quotes, not domestic share prices. INR display uses the dated daily USD–INR reference rate shown in the footer. It is not an intraday FX quote. One crore is 10 million rupees; one L crore is 100,000 crore.</li><li>Signed daily changes and 30-day trend paths were read from the source tables. Sparkline paths show the source’s relative trend; they do not provide a precise historical price series.</li><li>Missing metrics are shown as “—”. Absence from a ranking page does not mean zero. No values are invented or extrapolated.</li><li>Charts cover loaded companies only. Sector labels are editorial primary-business classifications. Figures from separate ranking snapshots should not be used to calculate same-date valuation ratios.</li><li>Company logos are supplied by CompaniesMarketCap / CompaniesLogo for editorial identification. All 595 snapshot entries have source logo URLs; a neutral icon appears if an image is unavailable.</li><li>Selected quote sources: official NSE and BSE end-of-day UDiFF reports, imported locally from the Data sources panel. Direct live exchange subscriptions are not connected. The legacy Global Datafeeds bridge remains inactive. Live listings are separate from snapshot financials and are not counted as unique companies. No API credential is sent to the browser.</li><li>Watchlists and comparison selections are saved in this browser, without an account. Live mode polls the local server every five seconds while its upstream WebSocket receives updates. No live subscription is configured yet. There is no trading functionality.</li></ul><h3>Company directory</h3><p>Daily symbol checks use Zerodha’s public Kite instrument master, cross-referenced with the Upstox company-equity directory for ISIN matching. No account is needed for this verified public endpoint. Directory prices are not treated as live quotes; Zerodha live market data is not connected.</p><p>Rankings incorporates the broker equity directory, matching exchange listings by ISIN where available. It includes selected company-equity groups on NSE and BSE and excludes funds, bonds and suspended securities. Availability in a broker directory is not a guarantee of exhaustive exchange coverage. Logo coverage is complete for the 595-company snapshot; other directory entries use a neutral icon when no verified logo mapping is available.</p><p><a href="https://upstox.com/developer/api-documentation/instruments/" target="_blank" rel="noopener">Upstox instrument directory ↗</a></p><h3>Sources</h3>${Object.entries(db.sources).map(([k,u])=>`<p><a target="_blank" rel="noopener" href="${u}">${metrics[k]} ranking · CompaniesMarketCap ↗</a></p>`).join('')}<h3>Feature coverage</h3><p>Available locally: rankings, search, sector and listing filters, currency conversion, watchlists, comparisons, CSV exports, company profiles and snapshot charts. Balance sheets, borrowing data, historical prices, dividends, stock splits and company reports have source links but no local dataset yet. ETFs, multilingual content and account syncing are not connected.</p></article>`}
document.body.classList.add('compact-rows');$('#theme').onclick=()=>{document.body.classList.toggle('dark');save('isv-dark',document.body.classList.contains('dark'))};if(read('isv-dark',false))document.body.classList.add('dark');$('#currency').onchange=e=>{currency=e.target.value==='INR'?'INR':'USD';save('isv-currency',currency);render()};$('#detail .close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search'))location.hash='rankings';setTimeout(()=>$('#search')?.focus(),30)}if(e.key==='Enter'&&e.target.matches('circle[data-company]'))openCompany(+e.target.dataset.company)});document.querySelector('.skip-link').onclick=e=>{e.preventDefault();$('#content').focus();$('#content').scrollIntoView({block:'start'})};window.onhashchange=()=>{page=1;render();window.scrollTo({top:0,behavior:'instant'})};$('#export').onclick=()=>{const ss=tab==='compare'?stocks.filter(s=>compare.includes(s.ticker)):['rankings','watchlist'].includes(tab)?chosen():stocks;const keys=['name','ticker','sector',...Object.keys(metrics),'price','sourcePriceINR','change','lastTrade'];const csv=[[`Data: ${officialSnapshotLabel()}; ${feedMode==='live'?'INR live feed':(officialReports().length?'Financials USD billions; price USD converted; sourcePriceINR official INR closes':'USD snapshot')}; signed daily change; source dates differ`],keys,...ss.map(s=>keys.map(k=>s[k]??''))].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='india-stock-view-'+tab+'-2026-10-30.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`Exported ${ss.length} rows · ${feedMode==='live'?'INR live quotes':(officialReports().length?'official closing prices and source financials':'original USD snapshot values')}`)};
Promise.all([fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('instruments.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([d,master])=>{db=d;snapshotStocks=d.stocks.map((s,i)=>({...s,rank:i+1,sector:getSector(s.name)}));instruments=master.listings;stocks=mergeRankingUniverse(snapshotStocks,instruments);initLive();compare=compare.filter(t=>stocks.some(s=>s.ticker===t));render()}).catch(()=>{$('#content').innerHTML='<div class="empty"><h3>We couldn’t load the company data.</h3><p>Refresh this page to try again.</p></div>'});

