function renderLiveStats(){const nse=stocks.filter(s=>s.exchange==='NSE'&&s.price!=null).length,bse=stocks.filter(s=>s.exchange==='BSE'&&s.price!=null).length;$('#stats').innerHTML=[['NSE LISTINGS RECEIVED',nse,'Separate exchange listings'],['BSE LISTINGS RECEIVED',bse,'Separate exchange listings'],['ADVANCERS',stocks.filter(s=>s.change>0).length,'Received quotes only'],['DECLINERS',stocks.filter(s=>s.change<0).length,'Received quotes only']].map(([label,value,note])=>`<div class="stat"><div class="stat-label">${label}</div><strong>${value.toLocaleString('en-IN')}</strong></div>`).join('');$('#watch-count').textContent=watch.size}
async function readFeed(){if(STATIC_PREVIEW)return {status:{state:'not_configured',provider:'Official exchange reports',configured:false},quotes:[]};try{const r=await fetch('/api/market',{cache:'no-store'});if(!r.ok)throw Error();const payload=await r.json();if(!payload.status||!Array.isArray(payload.quotes))throw Error();if(Array.isArray(payload.listings))liveDirectory=payload.listings;return payload}catch{return {status:{state:'not_configured',provider:'Global Datafeeds',configured:false},quotes:[]}}}
function updateFeedLabel(){const st=feedStatus?.state;$('#feed-state').classList.toggle('feed-connected',feedMode==='live'&&st==='streaming');if(feedMode==='snapshot')$('#feed-state').textContent=officialSnapshotLabel();else $('#feed-state').textContent=(st==='streaming'?'Feed connected':st==='disconnected'?'Disconnected · last received quotes':'Feed waiting')+' · '+(feedStatus?.received||0)+' quotes / '+stocks.length+' listings';$('#currency').disabled=false}
function showFeedPanel(){renderExchangeSources()}

function applyLiveQuotes(quotes){const lookup=new Map(snapshotStocks.filter(s=>/\.(NS|BO)$/.test(s.ticker)).map(s=>[(s.ticker.endsWith('.BO')?'BSE:':'NSE:')+s.ticker.replace(/\.(NS|BO)$/,''),s]));const byId=new Map(quotes.map(q=>[q.id,q]));const entries=liveDirectory.length?liveDirectory.map(d=>({...d,id:d.exchange+':'+d.symbol,...(byId.get(d.exchange+':'+d.symbol)||{})})):quotes;stocks=entries.map((q,i)=>{const meta=lookup.get(q.id);return {...q,ticker:q.id,rank:i+1,sector:meta?.sector||'Unclassified',name:meta?.name||q.name||q.symbol,logo:meta?.logo||null,cap:null}});updateFeedLabel()}
async function initLive(){const payload=await readFeed();feedStatus=payload.status;updateFeedLabel();$('#feed-button').onclick=async()=>{const payload=await readFeed();feedStatus=payload.status;showFeedPanel();$('#feed-dialog').showModal()};$('#feed-dialog .close').onclick=()=>$('#feed-dialog').close();if(STATIC_PREVIEW)return;setInterval(async()=>{if(document.hidden)return;const payload=await readFeed();feedStatus=payload.status;if(feedMode==='live'){applyLiveQuotes(payload.quotes);if(!$('#detail').open&&!$('#feed-dialog').open){const focused=document.activeElement?.id;if(focused!=='search')render();else{updateStats();renderRows()}}}},5000)}
function renderLiveCharts(){const gainers=stocks.filter(s=>s.change!=null).sort((a,b)=>b.change-a.change).slice(0,10),losers=stocks.filter(s=>s.change!=null).sort((a,b)=>a.change-b.change).slice(0,10);$('#content').innerHTML=`<div class="notice">Rankings cover received exchange listings, not unique companies or confirmed full-market coverage. Prices are INR. Stale quotes retain their trade timestamps.</div><div class="chart-grid">${[['Top gainers',gainers],['Top decliners',losers]].map(([title,ss])=>`<article class="card"><h3>${title}</h3>${ss.length?ss.map(s=>`<div class="bar-row"><button class="company-cell" data-company="${s.rank}">${escapeHtml(s.symbol)}</button><div class="bar-track"><div class="bar-fill" style="background:${s.change<0?'var(--down)':'var(--up)'};width:${Math.min(100,Math.abs(s.change)/Math.max(1,...ss.map(x=>Math.abs(x.change)))*100)}%"></div></div>${changeBadge(s)}</div>`).join(''):'<p class="note">Waiting for exchange quotes.</p>'}</article>`).join('')}</div>`;bindCompanies()}
let instruments=[],liveDirectory=[],directoryQuery='',directoryExchange='All exchanges',directoryPage=1;
async function renderDirectory(){if(!instruments.length){try{const response=await fetch('instruments.json');const master=await response.json();instruments=master.listings}catch{$('#content').innerHTML='<div class="empty">Company directory could not be loaded.</div>';return}}
const ss=instruments.filter(s=>(directoryExchange==='All exchanges'||s.exchange===directoryExchange)&&`${s.name} ${s.symbol} ${s.isin}`.toLowerCase().includes(directoryQuery.toLowerCase()));const pages=Math.max(1,Math.ceil(ss.length/PAGE_SIZE));directoryPage=Math.min(pages,directoryPage);const logos=new Map(snapshotStocks.filter(s=>/\.(NS|BO)$/.test(s.ticker)).map(s=>[s.ticker.replace(/\.(NS|BO)$/,''),s.logo]));
$('#content').innerHTML=`<div class="notice">${instruments.length.toLocaleString('en-IN')} company equity listings in the downloaded Upstox BOD directory · ${new Set(instruments.map(s=>s.isin)).size.toLocaleString('en-IN')} distinct ISINs · Quotes require the live feed. Excludes ETFs, bonds and suspended instruments. Directory download: 30 Oct 2026.</div><div class="controls"><label class="search">⌕ <input id="directory-search" aria-label="Search all listings" placeholder="Search company, symbol or ISIN…" value="${escapeHtml(directoryQuery)}"></label><select id="directory-exchange" aria-label="Directory exchange">${['All exchanges','NSE','BSE'].map(v=>option(v,v,directoryExchange)).join('')}</select><span class="coverage-chip">${ss.length.toLocaleString('en-IN')} listings</span></div><div class="table-wrap"><table><thead><tr><th class="left">Company</th><th>Symbol</th><th>Exchange</th><th>ISIN</th><th>Live quotes</th></tr></thead><tbody>${ss.slice((directoryPage-1)*PAGE_SIZE,directoryPage*PAGE_SIZE).map(s=>`<tr><td class="left"><span class="company-cell">${logo({...s,logo:logos.get(s.symbol)})}<span>${escapeHtml(s.name)}<small>${escapeHtml(s.group)} · company equity</small></span></span></td><td>${escapeHtml(s.symbol)}</td><td>${s.exchange}</td><td>${escapeHtml(s.isin)}</td><td class="note">Feed required</td></tr>`).join('')}</tbody></table>${!ss.length?'<div class="empty">No matching listings.</div>':''}</div><div class="pages"><span>Page ${directoryPage} of ${pages}</span><div><button id="directory-prev" ${directoryPage===1?'disabled':''}>← Previous</button><button id="directory-next" ${directoryPage===pages?'disabled':''}>Next →</button></div></div><p class="note">A company may have multiple exchange listings. Missing company logos use a neutral icon. <a class="source-link" href="https://upstox.com/developer/api-documentation/instruments/" target="_blank" rel="noopener">Directory source ↗</a></p>`;
$('#directory-search').oninput=e=>{const pos=e.target.selectionStart;directoryQuery=e.target.value;directoryPage=1;renderDirectory().then(()=>{$('#directory-search').focus();$('#directory-search').setSelectionRange(pos,pos)})};$('#directory-exchange').onchange=e=>{directoryExchange=e.target.value;directoryPage=1;renderDirectory()};$('#directory-prev').onclick=()=>{directoryPage--;renderDirectory()};$('#directory-next').onclick=()=>{directoryPage++;renderDirectory()};}

// Keep the rankings universe in sync with the server's refreshed directory.
setInterval(async()=>{if(STATIC_PREVIEW||document.hidden||feedMode!=='snapshot')return;try{const response=await fetch('instruments.json',{cache:'no-store'});if(!response.ok)return;const master=await response.json();const signature=master.listings.map(s=>s.exchange+':'+s.symbol+':'+s.isin).join('|');if(signature===instruments.map(s=>s.exchange+':'+s.symbol+':'+s.isin).join('|'))return;instruments=master.listings;stocks=mergeRankingUniverse(snapshotStocks,instruments);if(!$('#detail').open)render()}catch{}},60000);

updateCurrencyNotice();refreshCurrencyRate();

let compareTimeline=30;
function compareOverlay(selected){
 const palette=['#397de0','#e69326','#16a580','#b16bde'];
 const series=selected.map((stock,i)=>{const raw=stock.sparkline;if(!raw||!/^[ML0-9,. \-]+$/.test(raw))return null;const nums=raw.match(/-?\d+(?:\.\d+)?/g)?.map(Number)||[];let points=[];for(let j=0;j+1<nums.length;j+=2)points.push([nums[j],nums[j+1]]);if(points.length<2)return null;const end=points.at(-1)[0],start=end-(end-points[0][0])*compareTimeline/30;const index=points.findIndex(p=>p[0]>=start);if(index>0&&points[index][0]>start){const a=points[index-1],b=points[index],y=a[1]+(b[1]-a[1])*(start-a[0])/(b[0]-a[0]);points=[[start,y],...points.slice(index)]}else points=points.slice(Math.max(0,index));const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const xmin=Math.min(...xs),xspan=Math.max(...xs)-xmin,ymin=Math.min(...ys),yspan=Math.max(...ys)-ymin;if(!xspan)return null;return {stock,color:palette[i],path:points.map((p,j)=>`${j?'L':'M'}${(64+(p[0]-xmin)/xspan*796).toFixed(2)},${(32+(yspan?(p[1]-ymin)/yspan:0.5)*228).toFixed(2)}`).join(' ')};}).filter(Boolean);
 return `<article class="card compare-overlay"><div class="overlay-heading"><div><span class="eyebrow">STOCK OVERLAY</span><h3>${compareTimeline}-day trend comparison</h3></div>${chartTimelineControls('data-compare-range','1M',['1M'])}</div><p>Each stock is scaled to its own selected range: low = 0, high = 100. Compare the shape and timing of movements; this is not a percentage-return or price comparison.</p>${series.length?`<svg viewBox="0 0 900 310" class="overlay-chart" role="img" aria-label="Overlaid relative ${compareTimeline}-day stock trends, independently scaled from zero to one hundred">${[0,25,50,75,100].map(v=>{const y=260-v/100*228;return `<line x1="64" x2="860" y1="${y}" y2="${y}" class="chart-gridline"/><text x="49" y="${y+4}" text-anchor="end">${v}</text>`}).join('')}${series.map(s=>`<path d="${s.path}" fill="none" stroke="${s.color}" stroke-width="2.5" vector-effect="non-scaling-stroke" class="overlay-series" data-overlay="${escapeHtml(s.stock.ticker)}"><title>${escapeHtml(s.stock.name)} · independently scaled trend</title></path>`).join('')}${[0,1,2,3,4].map(i=>`<text x="${64+i/4*796}" y="290" text-anchor="${i===0?'start':i===4?'end':'middle'}">${relativeDateLabel(i/4,compareTimeline)}</text>`).join('')}</svg><div class="overlay-legend">${series.map(s=>`<button class="overlay-toggle" data-overlay-toggle="${escapeHtml(s.stock.ticker)}" aria-pressed="true"><i style="background:${s.color}"></i>${escapeHtml(s.stock.name)}</button>`).join('')}</div><p class="note">Axis dates are approximate; levels show relative range, not prices. Only 1M is available. Select a company in the legend to hide or show its line. Source: CompaniesMarketCap.</p>`:'<div class="stock-no-history"><h3>No trend data for these selections</h3><p>Add a company with an available 30-day trend to see its line here.</p></div>'}${selected.filter(s=>!series.some(x=>x.stock.ticker===s.ticker)).map(s=>`<p class="note">${escapeHtml(s.name)}: 30-day trend unavailable.</p>`).join('')}${selected.length===1?'<p class="note">Add another company above to compare trends.</p>':''}</article>`;
}
